package pvz.utils;

public class Position {
	
	private int row;
	private int col;
	
	public Position(int row, int col) {
		this.row = row;
		this.col = col;
	}

	public int row() {
		// TODO Auto-generated method stub
		return row;
	}
	
	public int col() {
		// TODO Auto-generated method stub
		return col;
	}
}
